// Map spreadsheet rows to the JSON contract the Android apps expect:
// GET -> { "jobs": [ {...}, ... ] }
const toBool = (v) => v === true || String(v).toLowerCase() === 'true';
const toNum = (v) => (v === '' || v === null || v === undefined) ? null : Number(v);

const jobs = $input.all()
  .map((item) => item.json)
  .filter((r) => r.id)
  .map((r) => ({
    id: String(r.id),
    date: String(r.date ?? ''),
    unit: String(r.unit ?? ''),
    category: String(r.category ?? 'UNKNOWN'),
    description: String(r.description ?? ''),
    status: String(r.status ?? 'PENDING'),
    needsReview: toBool(r.needsReview),
    reviewReason: String(r.reviewReason ?? ''),
    remarks: String(r.remarks ?? ''),
    customerCharge: toNum(r.customerCharge),
    contractorPayable: toNum(r.contractorPayable),
    invoiced: toBool(r.invoiced),
    paid: toBool(r.paid),
    createdBy: String(r.createdBy ?? ''),
    rawMessage: String(r.rawMessage ?? '')
  }));

return [{ json: { jobs } }];

// The app POSTs one job as JSON. Normalize it into one spreadsheet row.
const j = $json.body || {};
if (!j.id) {
  throw new Error('Missing job id in POST body');
}
const boolCell = (v) => (v === true || String(v).toLowerCase() === 'true') ? 'TRUE' : 'FALSE';
const numCell = (v) => (v === null || v === undefined || v === '') ? '' : Number(v);

return [{ json: {
  id: String(j.id),
  date: String(j.date ?? ''),
  unit: String(j.unit ?? ''),
  category: String(j.category ?? 'UNKNOWN'),
  description: String(j.description ?? ''),
  status: String(j.status ?? 'PENDING'),
  needsReview: boolCell(j.needsReview),
  reviewReason: String(j.reviewReason ?? ''),
  remarks: String(j.remarks ?? ''),
  customerCharge: numCell(j.customerCharge),
  contractorPayable: numCell(j.contractorPayable),
  invoiced: boolCell(j.invoiced),
  paid: boolCell(j.paid),
  createdBy: String(j.createdBy ?? ''),
  rawMessage: String(j.rawMessage ?? '')
} }];
